import { fetchUpstream } from '@/lib/upstream/upstream-client'
import { UpstreamRequestError } from '@/lib/upstream/upstream-errors'

const DOCUMENT_ID_PATTERN = /^\d+$/
const ONE_DAY_SECONDS = 60 * 60 * 24

const notFound = () => new Response('Not found', { status: 404 })

/** Streams the thumbnail generated by the upstream site for a document. */
export const GET = async (_request: Request, { params }: RouteContext<'/api/documents/[id]/preview'>) => {
  const { id } = await params
  if (!DOCUMENT_ID_PATTERN.test(id)) return notFound()

  try {
    const upstream = await fetchUpstream(`/docs/preview/${id}`)
    const contentType = upstream.headers.get('content-type') ?? ''
    if (!contentType.startsWith('image/')) return notFound()

    return new Response(upstream.body, {
      headers: {
        'content-type': contentType,
        'cache-control': `private, max-age=${ONE_DAY_SECONDS}`,
        'x-content-type-options': 'nosniff',
      },
    })
  } catch (error) {
    if (error instanceof UpstreamRequestError) return notFound()
    throw error
  }
}
